from pathlib import Path
import json,hashlib,collections
data=json.loads(Path('outputs/Digitone-E04-PC-live-context-trace.json').read_text())
assert data['passed'] and len(data['cases'])==1
r=data['cases'][0];t=r['trace'];checks={}
def check(name,condition):checks[name]=bool(condition);assert condition,name
def frame(x):
 b=bytes.fromhex(x['private_tail']);return [int.from_bytes(b[i:i+4],'big') for i in range(256,272,4)]
def evt(x,a):return next(e for e in x['events'] if int(e['address'],16)==a)
check('trace untruncated',len(t)<6000 and len(r['helper_paths'])<20000 and len(r['metadata_writes'])<10000)
check('no halt and exact payload',r['halted'] is None and r['payload_intact'] and r['ready']==1)
check('real DSP produced audio',r['DSP_after']['booted'] and r['DSP_after']['error'] is None and r['audio_nonzero_bytes']>0)
seq=next(x for x in t if x['label']=='commit' and x['stack'][3]!=0)
live=next(x for x in t if x['label']=='commit' and x['stack'][3]==0)
event=live['regs']['A3'];slot=int(evt(live,event)['slot'],16)
copies=[x for x in t if x['label']=='live raw copy direct' and x['stack'][0]==event and x['ms']<=live['ms']]
copy=copies[-1];done=next(x for x in t[t.index(copy)+1:] if x['label']=='live raw copy direct done')
source=copy['stack'][1]
alloc=next(x for x in reversed(r['allocations']) if int(x['event'],16)==event and x['ms']<=copy['ms'])
check('live allocated by creator return 400ff504',alloc['stack'][1]==0x400ff504)
check('live raw copy exact 72 bytes',copy['stack'][2]==72 and evt(done,event)['fields']==evt(copy,source)['fields'])
check('source descriptor outside existing metadata map',evt(copy,source)['slot'] is None)
check('live metadata zero before and after copying',evt(copy,event)['context']==evt(done,event)['context']=='0x0')
publish=next(x for x in t if x['label']=='stock immediate publish' and x['stack'][1]==event and copy['ms']<=x['ms']<=live['ms'])
check('immediate publication still context zero',evt(publish,event)['context']=='0x0')
epoch=[x for x in t if alloc['ms']<=x['ms']<=live['ms']]
check('capture wrapper misses live event generation',not any(x['label']=='producer_capture' and x['regs']['A2']==event for x in epoch))
writes=[x for x in r['metadata_writes'] if int(x['address'],16)==slot and alloc['ms']<=x['ms']<=live['ms']]
check('slot only cleared before selected live commit',bool(writes) and all(x['value']==0 and x['pc']=='0x47be030e' for x in writes))
check('existing event copy wrappers unused in this run',not any(x['label'] in ['copy','first_copy'] for x in t))
snap=next(x for x in t if x['label']=='snapshot return' and x['regs']['A3']==event and x['ms']==live['ms'])
check('snapshot reads owned slot as zero',snap['regs']['A0']==slot and snap['regs']['D0']==0)
check('sequencer commit supplies expected context',seq['stack'][3]==0x800000be)
check('old sequencer frame valid before live commit',frame(live)==[1,0x800000be,1,0x80000000])
ret=next(x for x in t[t.index(live)+1:] if x['label']=='commit return')
check('zero live commit succeeds and clears cookie',ret['regs']['D0']==1 and frame(ret)==[2,0,0,0])
read=next(x for x in t if x['label']=='read' and x['ms']>live['ms'])
check('pitch read sees completed zero frame',read['stack'][2:4]==[2,0] and frame(read)==[2,0,0,0])
path=[x['pc'] for x in r['helper_paths'] if x['name']=='read' and abs(x['ms']-read['ms'])<1e-7]
check('pitch read rejects cookie at 47be0106',path[path.index('0x47be0106')+1]=='0x47be010e' and '0x47be0108' not in path)
check('busy identity and track checks passed before cookie',all(p in path for p in ['0x47be00e6','0x47be00f0','0x47be00fc']))
check('live quantizer receives zero and passes pitch through',sum(q['word']=='0x0' for q in r['quantize'])==26 and all(q['actual']==q['note'] for q in r['quantize'] if q['word']=='0x0'))
check('sequencer quantizer transforms note with valid context',[(q['note'],q['actual']) for q in r['quantize'] if q['word']!='0x0']==[(60,59)])
previous=json.loads(Path('outputs/Digitone-E04-PC-restored-arp-DSP.json').read_text())['cases'][2]
check('note/context results match uninstrumented workload',[(q['note'],q['word'],q['actual']) for q in r['quantize']]==[(q['note'],q['word'],q['actual']) for q in previous['quantize']])
original=json.loads(Path('outputs/Digitone-E04-PC-ISA-correction-summary.json').read_text())['unchanged_originals']
check('original E04 images unchanged',all(hashlib.sha256(Path(f).read_bytes()).hexdigest()==v for f,v in original.items()))
summary={'passed':True,'PC_only':True,'firmware_modified':False,'checks':checks,'trace_events':len(t),'helper_path_events':len(r['helper_paths']),'metadata_writes':len(r['metadata_writes']),'selected_live_note':evt(done,event)['fields'][6]>>24,'live_event':hex(event),'source_descriptor':hex(source),'candidate_slot':hex(slot),'creator':'0x400ff3ec','allocator_return':hex(alloc['stack'][1]),'raw_copy_site':copy['pc'],'raw_copy_callee':'0x400fbad8','publish_site':publish['pc'],'publish_caller':hex(publish['stack'][0]),'selected_identity':live['stack'][2],'track':live['stack'][4],'sequencer_context':hex(seq['stack'][3]),'slot_writes_for_live_generation':writes,'frame_before_live_commit':frame(live),'frame_after_live_commit':frame(ret),'first_live_read_ms':read['ms'],'cookie_rejection_pc':'0x47be0106','raw_copy_counts':dict(collections.Counter(x['label'] for x in t if 'live raw' in x['label'])),'quantizer_calls':len(r['quantize']),'zero_context_quantizer_calls':26,'diagnosis':'Live input descriptor is copied into a newly cleared pool event and immediately queued without any context-capture/transfer hook. Selection commits the already-zero metadata; the pitch read rejects the intentionally cleared cookie.','limits':['One restored-state workload in the PC engine; no physical fault reproduction or cache/timing validation.','Only the direct raw-copy branch executes here; alternatives 400ff5ac and 400ff5d4 are statically identified but not exercised.','Source-descriptor pattern ownership and the appropriate capture point still require verification before a fix.','No new custom bytes, metadata injection, PC firmware container or device transmission.'],'unchanged_originals':original}
Path('outputs/Digitone-E04-PC-live-context-loss-summary.json').write_text(json.dumps(summary,indent=2)+'\n')
lines=['# Live-note context loss: creation-to-pitch trace','', 'The live note does not acquire context in this route. A different stock creator copies its descriptor into a freshly cleared pool event and immediately publishes it, bypassing the existing capture and copy hooks. Selection receives zero metadata and correctly disables retained context; the pitch helper subsequently returns the original note. This is a concrete patch-coverage gap in the observed PC workload, rather than evidence of an unexplained context corruption. Firmware remains unchanged.','', '## Observed path','',f"The first selected live note is MIDI {summary['selected_live_note']}, the E in the injected C/E/G chord. Its event is `{summary['live_event']}`. The earlier C does not become this selected live event; event addresses are analyzed from their last allocation, not assumed to keep ownership across recycling.",'', '| Stage | Evidence |','|---|---|',f"| Allocation | Stock live creator `400ff3ec` calls the allocator at `400ff4fe`, returning at `400ff504`. Its event slot `{summary['candidate_slot']}` is cleared by the existing allocation hook. |",f"| Descriptor copy | Call `400ff5f6 → 400fbad8` copies 72 stock bytes from `{summary['source_descriptor']}` to `{summary['live_event']}`. Source and destination fields match immediately afterward; metadata is still zero. |",'| Publication | Creator tail-jumps at `400ff60a` to the immediate publisher `40100252`; caller return is `400eb0a0`. This bypasses the ordered-timestamp publisher `40100178` used by the sequencer. |','| Capture coverage | No producer-capture call for this event generation and no nonzero write to its candidate slot. Existing `copy`/`first_copy` helpers are not entered in this run. |','| Selection snapshot | `47be0184` resolves the pool event to its recognized candidate slot and returns zero; slot recognition succeeds. |','| Commit | `47be004e` receives identity 2, word 0 and track 0 with busy count 1. It succeeds and replaces `[1, 800000be, 1, 80000000]` with `[2, 0, 0, 0]`. |','| Pitch read | At the first subsequent arp pitch, busy count and identity checks pass. Cookie comparison `47be0106` branches to `47be010e`, returning zero context because expected cookie `80000000` meets stored cookie 0. |','', 'The valid sequencer event provides context `800000be` and changes 60 to 59. All 26 subsequent zero-context quantizer calls pass their original pitch through. The instrumented note/context signature matches the preceding uninstrumented mixed workload. No halt, DSP error or payload change is observed.','', '## Static producer layout','', 'Creator `400ff3ec` builds live descriptors at `4321ff34 + track*2a18 + note_index*72 + 414`. For the selected track-0 note 64, this resolves to `43221548`. It then allocates a normal pool event, performs the raw descriptor copy and publishes through `40100252` under the stock publisher\'s interrupt mask. Two additional raw-copy sites, `400ff5ac` and `400ff5d4`, appear in the creator\'s alternate selection branch; neither executes in this workload.','', 'The source descriptor is outside the helper\'s recognized event-pool/cache metadata map. Redirecting this copy to the existing metadata-copy helper alone would therefore still read zero source context. The missing operation must capture the live descriptor\'s correct pattern context or transfer an already owned snapshot, rather than borrowing the previous sequencer context.','', '## Verification and next step','', f"{len(checks)} automated evidence checks pass. The focused trace contains {len(t)} boundary records, {len(r['helper_paths'])} helper instruction entries and {len(r['metadata_writes'])} private-storage writes, below all recording limits. Original E04 hashes are reverified unchanged. No corrected package or additional helper overlay was generated.",'', 'Next audit which receiving pattern owns the input record passed to `400ff3ec`, and where its original root/scale can be captured before descriptor copying/publication. Cover its direct and alternate copy paths, note-off selection changes, allocation failure and pattern replacement before implementing a PC-only fix. Do not weaken the final cookie guard: it is correctly rejecting absent context.','', 'Evidence: `Digitone-E04-PC-live-context-trace.json`, `Digitone-E04-PC-live-context-loss-summary.json`, `work/PC-context-helper-disassembly.txt`, and `work/PC-live-origin-disassembly.txt`. Physical startup failure, cache coherence, RAM ownership, timing and the corrected packaged-loader path remain outside this trace.']
Path('outputs/Digitone-E04-PC-live-context-loss-review.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print(json.dumps(summary,indent=2))
